#include "temperature_packet.h"
#include <cassert>
#include <iostream>
int main() {
  // Independent published Melexis read-word example, not generated by this code.
  const uint8_t readWord[]={0xB4,0x07,0xB5,0xD2,0x3A};
  assert(mlxPacketCrc(readWord,5)==0x30);
  uint8_t data[]={0xD2,0x3A,0x30}; float value=0;
  assert(decodeMlxTemperature(0x5A,0x07,data,value) && std::fabs(value-28.01f)<0.002f);
  data[0]^=1; assert(!decodeMlxTemperature(0x5A,0x07,data,value) && std::isnan(value));
  data[0]^=1; data[2]^=1; assert(!decodeMlxTemperature(0x5A,0x07,data,value));
  data[2]^=1; assert(!decodeMlxTemperature(0x5B,0x07,data,value));
  assert(!decodeMlxTemperature(0x5A,0x06,data,value));
  std::cout << "MLX90614 reference packets and corruption rejection: PASS\n";
}
